/**
 * Argon2id password hashing module (T2).
 *
 * Wraps `@node-rs/argon2` with the OWASP-minimum parameters sourced from
 * `AuthConfig` (memory >= 19 MiB, iterations >= 2, parallelism >= 1) and
 * exposes a small, injectable `PasswordHasher` plus convenience functions.
 *
 * The verification routine is the library's constant-time implementation; salts
 * are generated by the library per hash, so identical passwords never produce
 * identical digests.
 */

import { Algorithm, hash, parseOptions, verify } from '@node-rs/argon2';

import {
  DEFAULT_ARGON2_MEMORY_COST,
  DEFAULT_ARGON2_PARALLELISM,
  DEFAULT_ARGON2_TIME_COST,
  MAX_ARGON2_MEMORY_COST,
  MAX_ARGON2_PARALLELISM,
  MAX_ARGON2_TIME_COST,
  MIN_ARGON2_MEMORY_COST,
  MIN_ARGON2_PARALLELISM,
  MIN_ARGON2_TIME_COST,
} from './config.js';

/** Argon2id parameters, in the library's native naming. */
export interface Argon2Params {
  /** Memory cost in KiB (>= 19456 per OWASP). */
  memoryCost: number;
  /** Time cost / iterations (>= 2 per OWASP). */
  timeCost: number;
  /** Degree of parallelism (>= 1 per OWASP). */
  parallelism: number;
}

/** OWASP-minimum Argon2id parameters. */
export const OWASP_MIN_MEMORY_COST = MIN_ARGON2_MEMORY_COST;
export const OWASP_MIN_TIME_COST = MIN_ARGON2_TIME_COST;
export const OWASP_MIN_PARALLELISM = MIN_ARGON2_PARALLELISM;

/** Default (OWASP-minimum) parameters. */
export const DEFAULT_ARGON2_PARAMS: Argon2Params = {
  memoryCost: DEFAULT_ARGON2_MEMORY_COST,
  timeCost: DEFAULT_ARGON2_TIME_COST,
  parallelism: DEFAULT_ARGON2_PARALLELISM,
};

/** A small, injectable password-hashing capability. */
export interface PasswordHasher {
  hash(password: string): Promise<string>;
  verify(hash: string, password: string): Promise<boolean>;
}

/**
 * Validates Argon2id parameters against the OWASP minimums and configured
 * upper bounds. Throws an `Error` naming the offending field on failure.
 * Returns the validated params on success.
 */
export function validateArgon2Params(params: Argon2Params): Argon2Params {
  if (!Number.isInteger(params.memoryCost)) {
    throw new Error(`memoryCost must be an integer; received "${params.memoryCost}"`);
  }
  if (params.memoryCost < MIN_ARGON2_MEMORY_COST || params.memoryCost > MAX_ARGON2_MEMORY_COST) {
    throw new Error(
      `memoryCost must be between ${MIN_ARGON2_MEMORY_COST} and ${MAX_ARGON2_MEMORY_COST}; received "${params.memoryCost}"`,
    );
  }
  if (!Number.isInteger(params.timeCost)) {
    throw new Error(`timeCost must be an integer; received "${params.timeCost}"`);
  }
  if (params.timeCost < MIN_ARGON2_TIME_COST || params.timeCost > MAX_ARGON2_TIME_COST) {
    throw new Error(
      `timeCost must be between ${MIN_ARGON2_TIME_COST} and ${MAX_ARGON2_TIME_COST}; received "${params.timeCost}"`,
    );
  }
  if (!Number.isInteger(params.parallelism)) {
    throw new Error(`parallelism must be an integer; received "${params.parallelism}"`);
  }
  if (params.parallelism < MIN_ARGON2_PARALLELISM || params.parallelism > MAX_ARGON2_PARALLELISM) {
    throw new Error(
      `parallelism must be between ${MIN_ARGON2_PARALLELISM} and ${MAX_ARGON2_PARALLELISM}; received "${params.parallelism}"`,
    );
  }
  return params;
}

/**
 * Builds a `PasswordHasher` bound to the given (validated) parameters.
 */
export function createPasswordHasher(params: Argon2Params): PasswordHasher {
  validateArgon2Params(params);
  const options = {
    algorithm: Algorithm.Argon2id,
    memoryCost: params.memoryCost,
    timeCost: params.timeCost,
    parallelism: params.parallelism,
  };
  return {
    async hash(password: string): Promise<string> {
      return hash(password, options);
    },
    async verify(stored: string, password: string): Promise<boolean> {
      return verify(stored, password);
    },
  };
}

/**
 * Hashes a password with the supplied parameters (or OWASP defaults).
 */
export async function hashPassword(
  password: string,
  params: Argon2Params = DEFAULT_ARGON2_PARAMS,
): Promise<string> {
  return createPasswordHasher(params).hash(password);
}

/**
 * Verifies a password against a stored Argon2id hash using the library's
 * constant-time routine.
 */
export async function verifyPassword(stored: string, password: string): Promise<boolean> {
  return verify(stored, password);
}

/**
 * Re-exports the library's option parser so callers can inspect the parameters
 * encoded in a stored hash (e.g. for "needs rehash" checks).
 */
export { parseOptions };
